from sklearn.preprocessing import FunctionTransformer
import numpy as np

def log1p_clip(X):
    return np.log1p(np.clip(X, a_min=0, a_max=None))

transformer = FunctionTransformer(log1p_clip)
X_out = transformer.fit_transform(np.array([[1.0, 2.0], [3.0, 4.0]]))
